// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 seedAmount) public {
        uint256 amount = bound(seedAmount, 1, 1000 ether);
        address owner = address(uint160(uint256(keccak256(abi.encodePacked("owner")))));
        vm.assume(owner != address(0) && owner != address(c) && owner != address(this));
        vm.prank(owner);
        c = new SimpleWallet();
        vm.deal(address(c), amount);
        vm.prank(owner);
        c.withdrawAll();
        assertTrue(address(c).balance == 0);
    }
}
